BEGIN TRANSACTION;
CREATE TABLE "rules_alternative" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "lemma" varchar(255) NOT NULL, "word_types" varchar(255) NULL, "is_inspiration" bool NOT NULL, "is_active" bool NOT NULL, "label" varchar(255) NULL, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "rule_id" integer NOT NULL REFERENCES "rules_rule" ("id") DEFERRABLE INITIALLY DEFERRED, "source_id" integer NULL REFERENCES "rules_source" ("id") DEFERRABLE INITIALLY DEFERRED, "lemma_json" text NOT NULL CHECK ((JSON_VALID("lemma_json") OR "lemma_json" IS NULL)), "word_types_json" text NOT NULL CHECK ((JSON_VALID("word_types_json") OR "word_types_json" IS NULL)), "type" varchar(14) NOT NULL, "pluralization" varchar(13) NOT NULL, "is_placeholder" bool NOT NULL, "is_remove" bool NOT NULL, "language" varchar(2) NOT NULL, "is_advanced" bool NOT NULL);
CREATE TABLE "rules_englishadjective" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "base_form" varchar(255) NOT NULL UNIQUE, "comparative" varchar(255) NULL, "superlative" varchar(255) NULL, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "is_absolute" bool NOT NULL);
CREATE TABLE "rules_englishnoun" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "base_form" varchar(255) NOT NULL UNIQUE, "plural" varchar(255) NULL, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "rules_englishverb" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "base_form" varchar(255) NOT NULL UNIQUE, "past_tense" varchar(255) NULL, "past_participle" varchar(255) NULL, "present_participle" varchar(255) NULL, "third_person_singular" varchar(255) NULL, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "rules_falsepositive" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "rule_id" integer NOT NULL REFERENCES "rules_rule" ("id") DEFERRABLE INITIALLY DEFERRED, "false_positive" varchar(255) NOT NULL);
CREATE TABLE "rules_germanadjective" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "base_form" varchar(255) NOT NULL UNIQUE, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "comparative" varchar(255) NULL, "is_absolute" bool NOT NULL, "superlative" varchar(255) NULL);
CREATE TABLE "rules_germannoun" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "base_form" varchar(255) NOT NULL UNIQUE, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "female_form" varchar(255) NULL, "gender_1" varchar(9) NULL, "gender_2" varchar(9) NULL, "pl_dat" varchar(255) NULL, "pl_gen" varchar(255) NULL, "pl_nom_acc" varchar(255) NULL, "plural_only" bool NOT NULL, "sg_dat" varchar(255) NULL, "sg_gen" varchar(255) NULL, "sg_nom_acc" varchar(255) NULL, "singular_only" bool NOT NULL, "male_form" varchar(255) NULL);
CREATE TABLE "rules_germanverb" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "base_form" varchar(255) NOT NULL UNIQUE, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "conjunctive_ich" varchar(255) NULL, "helping_verb" varchar(255) NULL, "imperativ_plural" varchar(255) NULL, "imperativ_singular" varchar(255) NULL, "infinitiv_zu" varchar(255) NULL, "past_participle" varchar(255) NULL, "past_tense_ich" varchar(255) NULL, "present_du" varchar(255) NULL, "present_ich" varchar(255) NULL, "present_pronoun" varchar(255) NULL);
CREATE TABLE "rules_lemmatization" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" date NOT NULL, "updated_at" datetime NOT NULL, "comment" text NULL, "text" varchar(255) NOT NULL, "lemma" varchar(255) NOT NULL, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "language" varchar(2) NOT NULL, "is_plural" bool NOT NULL);
CREATE TABLE "rules_rule" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "language" varchar(2) NOT NULL, "lemma" varchar(255) NOT NULL, "word_types" varchar(255) NULL, "label" varchar(255) NULL, "is_context_aware" bool NOT NULL, "is_active" bool NOT NULL, "createdby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "ownedby_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "source_id" integer NULL REFERENCES "rules_source" ("id") DEFERRABLE INITIALLY DEFERRED, "lemma_json" text NOT NULL CHECK ((JSON_VALID("lemma_json") OR "lemma_json" IS NULL)), "word_types_json" text NOT NULL CHECK ((JSON_VALID("word_types_json") OR "word_types_json" IS NULL)), "is_marked_for_review" bool NOT NULL, "emoji" varchar(5) NULL, "explanation" varchar(255) NULL, "url" varchar(255) NULL, "text_id" varchar(255) NOT NULL, "type" varchar(9) NOT NULL, "label_type" varchar(40) NOT NULL, "first_is_word_type_lemmatize" bool NULL, "first_is_word_type_lower_case" bool NULL, "first_token" varchar(255) NULL, "diversity_dimension_json" text NOT NULL CHECK ((JSON_VALID("diversity_dimension_json") OR "diversity_dimension_json" IS NULL)), "has_training_sentences" bool NULL, "lemma_length" integer unsigned NULL CHECK ("lemma_length" >= 0), "pattern" varchar(255) NULL, "entity_type" varchar(10) NOT NULL, "pluralization" varchar(13) NOT NULL);
CREATE INDEX "rules_falsepositive_createdby_id_0fd6c5fc" ON "rules_falsepositive" ("createdby_id");
CREATE INDEX "rules_falsepositive_rule_id_b806a78a" ON "rules_falsepositive" ("rule_id");
