CREATE INDEX "rules_alter_is_acti_671a5f_idx" ON "rules_alternative" ("is_active", "rule_id", "is_placeholder", "is_inspiration", "pluralization", "order");
CREATE INDEX "rules_rule_createdby_id_79ec44ec" ON "rules_rule" ("createdby_id");
CREATE INDEX "rules_rule_ownedby_id_434bfe5b" ON "rules_rule" ("ownedby_id");
CREATE INDEX "rules_rule_source_id_f7de9704" ON "rules_rule" ("source_id");
CREATE INDEX "rules_rule_is_acti_3e9519_idx" ON "rules_rule" ("is_active", "language", "type", "first_token", "first_is_word_type_lemmatize", "first_is_word_type_lower_case");
CREATE UNIQUE INDEX "rules_rule_language_lemma_word_types_type_pluralization_39ad25e7_uniq" ON "rules_rule" ("language", "lemma", "word_types", "type", "pluralization");
DELETE FROM "sqlite_sequence";
COMMIT;
